```kotlin
class UserAdapter(private var items: List<User>) :
    RecyclerView.Adapter<UserAdapter.ViewHolder>() {

    class ViewHolder(view: View) : RecyclerView.ViewHolder(view) {
        val name: TextView = view.findViewById(R.id.name)   // cached once
        val avatar: ImageView = view.findViewById(R.id.avatar)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_user, parent, false)
        return ViewHolder(view)   // called rarely — only when the pool needs a new instance
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        val user = items[position]
        holder.name.text = user.name   // called on every scroll-triggered rebind
        holder.avatar.loadImage(user.avatarUrl)
    }

    override fun getItemCount() = items.size
}
```

The split between `onCreateViewHolder` (rare — inflation and the one-time `findViewById` caching) and `onBindViewHolder` (frequent — runs on every scroll-triggered rebind) is the whole performance model made concrete: anything expensive belongs in the rare method, and `onBindViewHolder` should stay as cheap as possible since it runs constantly during a scroll gesture.
